  item: ResourceRequestListRead;
  facilityId: string;
  isOutgoing: boolean;
  active: boolean;
}) {
  const { t } = useTranslation();
  const readyToBook =
    !isOutgoing && item.status === ResourceRequestStatus.APPROVED;

  return (
    <li>
      <Link
        href={`/facility/${facilityId}/ccn/${item.id}${
          isOutgoing ? "?tab=outgoing" : ""
