          <span className="truncate text-sm font-medium">
            {item.title || t("ccn_untitled_request")}
          </span>
          <Badge
            variant={STATUS_BADGE_VARIANTS[item.status] ?? "secondary"}
            className="shrink-0 text-[10px]"
          >
            {t(`resource_request_status__${item.status}`)}
