          <DetailRow
            label={t("patient")}
            value={resource.related_patient?.name ?? "—"}
          />
          <DetailRow
            label={t("category")}
            value={t(
              `resource_request_category__${getResourceRequestCategoryEnum(
                resource.category,
              )}`,
            )}
          />
          <DetailRow
            label={t("origin_facility")}
            value={resource.origin_facility?.name ?? "—"}
          />
          {resource.reason ? (
            <DetailRow label={t("reason")} value={resource.reason} />
          ) : null}
        </CardContent>
      </Card>

