105	    }),
106	    enabled: !!transactionId,
107	    refetchInterval: awaiting ? POLL_MS : false,
108	  });
109	
110	  const status = statusQuery.data?.status;
111	  const sliceAction = sliceActionFor(status);
112	
113	  const sliceQuery = useQuery<BecknSlice>({
114	    queryKey: ["beckn", "slice", transactionId, sliceAction],
115	    queryFn: query(becknApi.slice, {
116	      pathParams: { transactionId: transactionId as string },
117	      queryParams: { action: sliceAction as string },
118	    }),
119	    enabled: !!transactionId && !!sliceAction,
120	    refetchInterval: (q) => (q.state.data?.ready ? false : SLICE_POLL_MS),
121	  });
122	
123	  // Stop polling once the awaited callback (matching `ON_*`) or a terminal error
124	  // arrives — it's now the FE's turn (or the flow has failed).
125	  useEffect(() => {
126	    if (!awaiting) return;
127	    const expected = `ON_${awaiting.toUpperCase()}`;
128	    if (status === expected || status === "NACK" || status === "ERROR") {
